# =============================================================================# SCRIPT BACKUP DATABASE OTOMATIS - SIMPEG-APP# Dijalankan otomatis oleh Windows Task Scheduler setiap hari jam 02:00# =============================================================================# --- Konfigurasi ---$ContainerName   = "simpeg-db"$DbName          = "simpeg"$DbUser          = "root"$DbPassword      = "rootpassword_simpeg_2024"$BackupBaseDir   = "C:\simpeg-backup\db"$LogFile         = "C:\simpeg-backup\logs\backup.log"$KeepDays        = 30   # Hapus backup lebih dari 30 hari# --- Fungsi Logging ---function Write-Log {    param([string]$Message)    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"    $entry = "[$timestamp] $Message"    Write-Host $entry    Add-Content -Path $LogFile -Value $entry}# --- Buat Direktori Jika Belum Ada ---if (-not (Test-Path $BackupBaseDir)) { New-Item -ItemType Directory -Path $BackupBaseDir -Force | Out-Null }if (-not (Test-Path (Split-Path $LogFile))) { New-Item -ItemType Directory -Path (Split-Path $LogFile) -Force | Out-Null }Write-Log "============================================"Write-Log "Mulai proses backup database SIMPEG..."# --- Cek apakah Docker berjalan ---try {    $dockerStatus = docker inspect --format="{{.State.Running}}" $ContainerName 2>&1    if ($dockerStatus -ne "true") {        Write-Log "ERROR: Container '$ContainerName' tidak berjalan. Backup dibatalkan."        exit 1    }} catch {    Write-Log "ERROR: Docker tidak dapat diakses - $_"    exit 1}# --- Jalankan mysqldump di dalam container ---$timestamp  = Get-Date -Format "yyyyMMdd_HHmmss"$BackupFile = "$BackupBaseDir\simpeg_$timestamp.sql"$GzipFile   = "$BackupFile.gz"Write-Log "Menjalankan mysqldump untuk database '$DbName'..."docker exec $ContainerName sh -c "mysqldump -u$DbUser -p$DbPassword --single-transaction --quick --lock-tables=false $DbName" | Out-File -FilePath $BackupFile -Encoding UTF8if ($LASTEXITCODE -ne 0) {    Write-Log "ERROR: mysqldump gagal dengan exit code $LASTEXITCODE"    Remove-Item -Path $BackupFile -Force -ErrorAction SilentlyContinue    exit 1}# --- Kompres file backup ---Write-Log "Mengompres file backup..."$BackupContent = Get-Content $BackupFile -Raw -Encoding UTF8$bytes = [System.Text.Encoding]::UTF8.GetBytes($BackupContent)$gzipStream = [System.IO.File]::Create($GzipFile)$gzip = New-Object System.IO.Compression.GZipStream($gzipStream, [System.IO.Compression.CompressionMode]::Compress)$gzip.Write($bytes, 0, $bytes.Length)$gzip.Close()$gzipStream.Close()Remove-Item -Path $BackupFile -Force$sizeMB = [math]::Round((Get-Item $GzipFile).Length / 1MB, 2)Write-Log "Backup berhasil: $GzipFile ($sizeMB MB)"# --- Hapus backup lama (lebih dari $KeepDays hari) ---Write-Log "Membersihkan backup lama (lebih dari $KeepDays hari)..."$oldFiles = Get-ChildItem -Path $BackupBaseDir -Filter "*.sql.gz" |            Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-$KeepDays) }foreach ($file in $oldFiles) {    Remove-Item -Path $file.FullName -Force    Write-Log "Dihapus (terlalu lama): $($file.Name)"}$totalBackups = (Get-ChildItem -Path $BackupBaseDir -Filter "*.sql.gz").CountWrite-Log "Total file backup tersimpan: $totalBackups file"Write-Log "Backup selesai."Write-Log "============================================"